type Counts = {windows:number;frames:number;contactIds:number;sledPoints:number;reads:Record<string,number>;distinct:Record<string,number>};
const groups:Record<string,Counts>={};let origin='scalar';
const count=()=>groups[origin]??=( {windows:0,frames:0,contactIds:0,sledPoints:0,reads:{},distinct:{}});
export function beginScalarObservation(){origin='scalar';}
export function beginObservationWindow(start:number,end:number){
 const stack=new Error().stack??'';
 origin=stack.includes('openInterval')?'interval-prefix':stack.includes('replayCandidate')?'candidate-replay':stack.includes('finalizeArcTrack')?'final-replay':'other-window';
 count().windows++;
}
export function probeRawFrame<T extends {position:object;velocity:object;contactLineIds:number[];sledContacts:string[]}>(row:T):T{
 const stats=count();stats.frames++;stats.contactIds+=row.contactLineIds.length;stats.sledPoints+=row.sledContacts.length;
 const seen=new Set<string>();
 const read=(key:string)=>{stats.reads[key]=(stats.reads[key]??0)+1;if(!seen.has(key)){seen.add(key);stats.distinct[key]=(stats.distinct[key]??0)+1;}};
 const vectors=new Map<string,object>();
 for(const name of ['sledContacts','contactLineIds'] as const){const values=row[name];vectors.set(name,new Proxy(values,{get(target,key,receiver){if(key==='length')read(name+'.length');else if(typeof key==='string'&&/^(0|[1-9][0-9]*)$/.test(key))read(name+'.element');return Reflect.get(target,key,receiver);}}));}
 for(const name of ['position','velocity'] as const){const v=row[name];vectors.set(name,new Proxy(v,{get(target,key,receiver){if(key==='x'||key==='y')read(name+'.'+key);return Reflect.get(target,key,receiver);}}));}
 return new Proxy(row,{get(target,key,receiver){if(typeof key==='string'&&Object.hasOwn(target,key)){read(key);if(vectors.has(key))return vectors.get(key);}return Reflect.get(target,key,receiver);}});
}
export function observationDemand(){return groups;}

