//! Conservative bounds on the existing rounded perpendicular predicate.
//! Packet order is unchanged. A bound may only prove that every line misses.
use crate::line::Line;
#[derive(Clone,Copy)]
pub(crate) struct PacketBounds { low:[f64;4], high:[f64;4], valid:bool }
impl PacketBounds {
 pub(crate) fn new()->Self {Self{low:[f64::INFINITY;4],high:[f64::NEG_INFINITY;4],valid:true}}
 pub(crate) fn extend(&mut self,line:&Line){
  for (i,v) in [line.p1x,line.p1y,line.normx,line.normy].into_iter().enumerate(){
   if !v.is_finite(){self.valid=false;}
   self.low[i]=self.low[i].min(v);self.high[i]=self.high[i].max(v);
  }
 }
 pub(crate) fn excludes(&self,x:f64,y:f64)->bool {
  if !self.valid||!x.is_finite()||!y.is_finite(){return false;}
  let Some(a)=products(self.low[2],self.high[2],x-self.high[0],x-self.low[0]) else{return false;};
  let Some(b)=products(self.low[3],self.high[3],y-self.high[1],y-self.low[1]) else{return false;};
  // Every actual rounded multiply/add lies inside these endpoint bounds.
  // NaN sums fail both comparisons and therefore retain the original loop.
  let low=a.0+b.0;let high=a.1+b.1;
  if low.is_nan()||high.is_nan(){return false;}
  high<=0.0||low>=crate::line::MAX_FORCE_LENGTH
 }
}
fn products(a:f64,b:f64,c:f64,d:f64)->Option<(f64,f64)>{
 let p=[a*c,a*d,b*c,b*d];
 if p.iter().any(|v|v.is_nan()){return None;}
 Some((p.iter().copied().fold(f64::INFINITY,f64::min),p.iter().copied().fold(f64::NEG_INFINITY,f64::max)))
}
#[cfg(test)]
mod tests {
 use super::*;
 #[test] fn packet_exclusion_implies_each_original_rounded_predicate_misses(){
  let mut seed=771236581u64;
  let mut next=||{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;(seed>>11) as f64/(1u64<<53) as f64};
  for scale in [1e-150,1e-20,1.0,1e6,1e150] {
