    for _ in 0..32 {let x=(next()-0.5)*scale;let y=(next()-0.5)*scale;if bounds.excludes(x,y){for l in &lines{let p=l.normx*(x-l.p1x)+l.normy*(y-l.p1y);assert!(!(p>0.0&&p<crate::line::MAX_FORCE_LENGTH));}}}
   }
  }
 }
